"use strict";(function(){const SLIDER_SELECTOR="[data-gstore-hero-slider]";const AUTOPLAY_DELAY=7e3;const MOBILE_BREAKPOINT=781;function initSlider(slider){const forceAutoplay=slider.hasAttribute("data-gstore-hero-force-autoplay");const desktopTrack=slider.querySelector("[data-gstore-hero-track]");const desktopSlides=Array.from(slider.querySelectorAll("[data-gstore-hero-slide]"));const desktopDots=Array.from(slider.querySelectorAll("[data-gstore-hero-dot]"));const mobileTrack=slider.querySelector("[data-gstore-hero-track-mobile]");const mobileSlides=Array.from(slider.querySelectorAll("[data-gstore-hero-slide-mobile]"));const mobileDots=Array.from(slider.querySelectorAll("[data-gstore-hero-dot-mobile]"));const desktopDotsContainer=slider.querySelector(".Gstore-hero-slider__dots--desktop");const mobileDotsContainer=slider.querySelector(".Gstore-hero-slider__dots--mobile");const prevButton=slider.querySelector("[data-gstore-hero-prev]");const nextButton=slider.querySelector("[data-gstore-hero-next]");let desktopIndex=0;let mobileIndex=0;let autoplayId=null;const prefersReducedMotion=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;function isMobile(){return window.innerWidth<=MOBILE_BREAKPOINT}function getCurrentSliderElements(){if(isMobile()){return{track:mobileTrack,slides:mobileSlides,dots:mobileDots,getCurrentIndex:function(){return mobileIndex},setCurrentIndex:function(val){mobileIndex=val}}}return{track:desktopTrack,slides:desktopSlides,dots:desktopDots,getCurrentIndex:function(){return desktopIndex},setCurrentIndex:function(val){desktopIndex=val}}}function canAutoplay(){const elements=getCurrentSliderElements();return elements.slides.length>1&&(forceAutoplay||!prefersReducedMotion)}function getActiveDotIndex(total,slideIndex){if(total<=3){return slideIndex}if(slideIndex===0){return 0}if(slideIndex===total-1){return 2}return 1}function getDotTargetIndex(dot,total,attributeName,fallbackIndex){const rawValue=dot.getAttribute(attributeName);if(rawValue==="middle"){return Math.floor(total/2)}if(rawValue!==null&&rawValue!==""){const parsed=Number.parseInt(rawValue,10);if(!Number.isNaN(parsed)){return parsed}}if(total<=3){return fallbackIndex}if(fallbackIndex===0){return 0}if(fallbackIndex===2){return total-1}return Math.floor(total/2)}function syncDotsVisibility(){if(desktopDotsContainer){desktopDotsContainer.setAttribute("aria-hidden",String(isMobile()))}if(mobileDotsContainer){mobileDotsContainer.setAttribute("aria-hidden",String(!isMobile()))}}function updateDots(index){const elements=getCurrentSliderElements();if(!elements.dots.length){return}const total=elements.slides.length;const activeDotIndex=getActiveDotIndex(total,index);elements.dots.forEach(function(dot,dotIndex){const isActive=dotIndex===activeDotIndex;dot.classList.toggle("is-active",isActive);dot.setAttribute("aria-selected",String(isActive))})}function goTo(index){const elements=getCurrentSliderElements();if(!elements.track||elements.slides.length===0){return}const total=elements.slides.length;const newIndex=(index+total)%total;elements.setCurrentIndex(newIndex);const offset=newIndex*100;elements.track.style.transform="translate3d(-"+offset+"%, 0, 0)";updateDots(newIndex)}function nextSlide(){const elements=getCurrentSliderElements();goTo(elements.getCurrentIndex()+1)}function prevSlide(){const elements=getCurrentSliderElements();goTo(elements.getCurrentIndex()-1)}function stopAutoplay(){if(autoplayId){window.clearInterval(autoplayId);autoplayId=null}}function startAutoplay(){if(!canAutoplay()){return}stopAutoplay();autoplayId=window.setInterval(nextSlide,AUTOPLAY_DELAY)}function handleResize(){stopAutoplay();if(desktopTrack&&desktopSlides.length>0){const offset=desktopIndex*100;desktopTrack.style.transform="translate3d(-"+offset+"%, 0, 0)"}if(mobileTrack&&mobileSlides.length>0){const offset=mobileIndex*100;mobileTrack.style.transform="translate3d(-"+offset+"%, 0, 0)"}syncDotsVisibility();updateDots(getCurrentSliderElements().getCurrentIndex());startAutoplay()}if(prevButton){prevButton.addEventListener("click",function(){prevSlide();if(canAutoplay()){stopAutoplay();startAutoplay()}})}if(nextButton){nextButton.addEventListener("click",function(){nextSlide();if(canAutoplay()){stopAutoplay();startAutoplay()}})}if(desktopDots.length){desktopDots.forEach(function(dot,index){dot.addEventListener("click",function(){if(!isMobile()){const total=desktopSlides.length;const targetIndex=getDotTargetIndex(dot,total,"data-gstore-hero-dot",index);desktopIndex=targetIndex;goTo(targetIndex);if(canAutoplay()){stopAutoplay();startAutoplay()}}})})}if(mobileDots.length){mobileDots.forEach(function(dot,index){dot.addEventListener("click",function(){if(isMobile()){const total=mobileSlides.length;const targetIndex=getDotTargetIndex(dot,total,"data-gstore-hero-dot-mobile",index);mobileIndex=targetIndex;goTo(targetIndex);if(canAutoplay()){stopAutoplay();startAutoplay()}}})})}slider.addEventListener("mouseenter",stopAutoplay);slider.addEventListener("mouseleave",startAutoplay);slider.addEventListener("focusin",stopAutoplay);slider.addEventListener("focusout",startAutoplay);let resizeTimeout;window.addEventListener("resize",function(){clearTimeout(resizeTimeout);resizeTimeout=setTimeout(handleResize,150)});syncDotsVisibility();updateDots(getCurrentSliderElements().getCurrentIndex());startAutoplay()}function init(){const sliders=document.querySelectorAll(SLIDER_SELECTOR);if(!sliders.length){return}sliders.forEach(initSlider)}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();
